item.command:
/usr/bin/bash -lc "perl -Mstrict -Mwarnings -e '
my @rows;
open my "'$fh, "<", "/workspace/final_answer/differential_expression.tsv" or die $!;
my $header = <$fh>;
while (my $line = <$fh>) {
  chomp $line;
  my @f = split /'"\\t/, "'$line, -1;
  push @rows, { gene => $f[0], p => 0 + $f[2], fdr => 0 + $f[3] };
}
my $m = @rows;
my @idx = sort { $rows[$a]{p} <=> $rows[$b]{p} } 0..$#rows;
my @adj;
my $min = 1;
for (my $rank = $m; $rank >= 1; $rank--) {
  my $i = $idx[$rank-1];
  my $val = $rows[$i]{p} * $m / $rank;
  $val = 1 if $val > 1;
  $min = $val if $val < $min;
  $adj[$i] = $min;
}
my $bad = 0;
my $maxdiff = 0;
for my $i (0..$#rows) {
  my $diff = abs($adj[$i] - $rows[$i]{fdr});
  $maxdiff = $diff if $diff > $maxdiff;
  $bad++ if $diff > 1e-12;
}
print "bh_rows=$m bh_bad=$bad max_abs_diff=$maxdiff'"\\n\";
exit("'$bad ? 1 : 0);
'"'"

